import {esc,money,paymentFeedback} from '../config.mjs';
import {LAB_API,LAB_KEY} from './lab-config.mjs';
export async function renderLaboratory(app,getToken,onBack){
 const request=async(action,body={})=>{const r=await fetch(LAB_API,{method:'POST',headers:{'content-type':'application/json',apikey:LAB_KEY,Authorization:'Bearer '+await getToken()},body:JSON.stringify({action,...body}),signal:AbortSignal.timeout(20000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Falha no laboratório.');return d};
 app.innerHTML=`<section><div class="eyebrow">Controle administrativo</div><h1>Laboratório do cliente</h1><div class="lab-banner"><strong>AMBIENTE DE TESTES · SANDBOX</strong><p>Somente dados fictícios. Os cenários são gravados no projeto separado hocco-mp-sandbox. Nenhuma ação desta tela cobra, reembolsa ou publica no app real.</p></div><div class="actions"><button class="btn secondary small" id="lab-back">Voltar ao administrativo</button><button class="btn secondary small" id="lab-refresh">Atualizar testes</button><button class="btn danger small" id="lab-clear">Limpar meus testes</button></div><div class="note"><strong>Integração Mercado Pago: não verificada neste laboratório.</strong><p>Os botões abaixo simulam eventos e reutilizam a moderação e a validação financeira do código. Eles não executam o checkout real nem certificam o webhook de produção.</p></div><form id="lab-form" class="paper"><h2>Nova participação fictícia</h2><div class="field"><label for="lab-kind">Modalidade</label><select id="lab-kind" name="kind"><option value="community">Comunidade · R$ 3,50</option><option value="live">LIVE · R$ 5,50</option><option value="video">Vídeo · valor fictício R$ 5,00</option><option value="sponsor">Patrocínio · R$ 39,90</option></select></div><div class="field"><label for="lab-message">Mensagem de teste</label><textarea id="lab-message" name="message" maxlength="180" required>Teste da comunidade HOCCO</textarea></div><button class="btn purple" type="submit">Criar cenário no sandbox</button></form><p id="lab-error" class="error" role="alert"></p><div id="lab-results" class="lab-results"></div></section>`;
 const $=id=>app.querySelector(id),error=$('#lab-error');
 const draw=rows=>{$('#lab-results').innerHTML=rows.map(row=>{const s=row.payload;return `<article><div class="eyebrow">SIMULAÇÃO · ${esc(s.kind)}</div><strong>@teste_hocco · ${esc(s.member_name)}</strong><p>${esc(s.message)}</p><p>${money(s.price_cents)} · revisão: ${esc(s.review)} · pagamento: ${esc(s.payment)}</p>${s.blocked?'<div class="note">Conteúdo bloqueado antes do pagamento.</div>':paymentFeedback(s,s.kind)}<dl><dt>Persistido no sandbox</dt><dd>${esc(row.id)}</dd><dt>Versão do simulador</dt><dd>${esc(s.engine_version||'v1')}</dd><dt>Criado em</dt><dd>${esc(new Date(row.created_at).toLocaleString('pt-BR'))}</dd><dt>Revisão do registro</dt><dd>${row.revision}</dd><dt>Publicação simulada</dt><dd>${esc(s.published_at||'Não publicada')}</dd></dl><div class="actions">${!s.blocked&&s.review!=='approved'?`<button class="btn secondary small" data-lab-id="${row.id}" data-operation="approve">Simular aprovação</button>`:''}${!s.blocked&&s.payment!=='refunded'?`<button class="btn purple small" data-lab-id="${row.id}" data-operation="pay">${s.payment==='confirmed'?'Repetir confirmação (idempotência)':'Simular pagamento aprovado'}</button>`:''}${s.payment==='confirmed'?`<button class="btn secondary small" data-lab-id="${row.id}" data-operation="refund">Simular devolução</button>`:''}${s.kind==='live'&&s.payment==='confirmed'?`<button class="btn secondary small" data-lab-id="${row.id}" data-operation="read">Simular leitura</button>`:''}${s.kind==='video'&&s.payment==='confirmed'?`<button class="btn secondary small" data-lab-id="${row.id}" data-operation="publish_video">Simular veiculação</button>`:''}</div></article>`}).join('')||'<div class="empty">Nenhum cenário de teste.</div>';app.querySelectorAll('[data-lab-id]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{error.textContent='';await request('lab.transition',{id:button.dataset.labId,operation:button.dataset.operation});await refresh()}catch(e){error.textContent=e.message;button.disabled=false}})};
 const refresh=async()=>{try{const d=await request('lab.list');draw(d.scenarios||[])}catch(e){error.textContent=e.message}};
 $('#lab-back').onclick=onBack;$('#lab-refresh').onclick=refresh;
 $('#lab-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;error.textContent='';try{const f=new FormData(e.target);await request('lab.create',{kind:f.get('kind'),message:f.get('message')});await refresh()}catch(e){error.textContent=e.message}finally{b.disabled=false}};
 $('#lab-clear').onclick=async()=>{if(!confirm('Apagar somente os cenários fictícios que você criou neste laboratório? O app público não será alterado.'))return;try{await request('lab.clear',{confirm:true});await refresh()}catch(e){error.textContent=e.message}};
 await refresh();
}
